'use strict';
// One bounded, read-only probe of the existing Listmonk database. No transport.
const fs=require('node:fs'),crypto=require('node:crypto');
const hash=v=>crypto.createHash('sha256').update(typeof v==='string'?v:JSON.stringify(v)).digest('hex');
const manifest=JSON.parse(fs.readFileSync('/app/native-backend/manifest.json'));
const {Client}=require('/app/native-backend/native-pg-driver.cjs').loadPGDriver(manifest.pgDriverManifestSha256);
const pg=new Client({host:'comunicacao_postgres',port:5432,database:'listmonk',user:'postgres',password:process.env.PGPASSWORD,connectionTimeoutMillis:10000,query_timeout:30000,application_name:'shrigma-crm-read-proof-20261014'});
let timer=setTimeout(()=>{console.error('CRM_READ_TASK_TIMEOUT');process.exit(1);},90000);
async function main(){
 await pg.connect();delete process.env.PGPASSWORD;
 await pg.query("BEGIN READ ONLY;SET LOCAL statement_timeout='25s';SET LOCAL lock_timeout='500ms';");
 const out={schema:'shrigma-crm-database-read-proof-v1',at:new Date().toISOString(),database:'listmonk',readOnly:true};
 out.server=(await pg.query("SELECT current_database() AS database,current_user AS role,current_setting('server_version_num') AS version")).rows[0];
 out.function=(await pg.query("SELECT p.oid,octet_length(p.prosrc) AS bytes,encode(sha256(convert_to(p.prosrc,'UTF8')),'hex') AS sha256,p.proconfig,p.proowner::regrole::text AS owner FROM pg_proc p WHERE p.oid='crm_audience_v2.shopify_ingest_chunk(jsonb,integer,jsonb)'::regprocedure")).rows[0];
 out.sources=(await pg.query("SELECT s.brand,s.current_operation,s.producer_revision,s.field_hashes,crm_audience_v2.shopify_snapshot(s.brand) AS snapshot,(SELECT count(*) FROM crm_audience_v2.shopify_customer_fact f WHERE f.brand=s.brand AND f.operation_id=s.current_operation) AS current_fact_rows,(SELECT count(*) FROM crm_audience_v2.shopify_customer_product p WHERE p.brand=s.brand AND p.operation_id=s.current_operation) AS current_product_rows,(SELECT count(*) FROM crm_audience_v2.shopify_product_history_gap g WHERE g.brand=s.brand AND g.operation_id=s.current_operation) AS current_gap_rows FROM crm_audience_v2.shopify_source s WHERE brand IN ('fish','aristo') ORDER BY brand")).rows;
 out.activeLease=(await pg.query("SELECT EXISTS(SELECT 1 FROM crm_audience_v2.shopify_sync_operation WHERE state NOT IN ('completed','blocked') AND lease_until>clock_timestamp()) OR EXISTS(SELECT 1 FROM crm_audience_v2.shopify_sync_mutex WHERE operation_id IS NOT NULL AND lease_until>clock_timestamp()) AS active")).rows[0].active;
 out.columns=(await pg.query("SELECT table_schema,table_name,column_name,data_type FROM information_schema.columns WHERE (table_schema='public' AND table_name IN ('shrigma_api_idempotencia','shrigma_template_draft','shrigma_template_email_registry','lists','templates')) OR (table_schema='crm_audience_v2' AND table_name IN ('audience','segment','config')) ORDER BY table_schema,table_name,ordinal_position")).rows;
 if(out.columns.some(x=>x.table_schema==='crm_audience_v2'&&x.table_name==='audience'&&x.column_name==='id'))out.audiences=(await pg.query("SELECT id,brand,version,archived,definition_hash,context_hash FROM crm_audience_v2.audience WHERE brand IN ('fish','aristo') ORDER BY brand,id LIMIT 200")).rows;
 if(out.columns.some(x=>x.table_name==='shrigma_api_idempotencia'&&x.column_name==='request_payload')){
   const result=await pg.query("SELECT chave,rota,actor,request_payload,resposta FROM public.shrigma_api_idempotencia WHERE request_payload->'rascunho'->>'nome'=$1 LIMIT 20",['teste-emails-fish']);
   out.modelOperations=result.rows.map(x=>({id:x.chave,action:x.rota,actorSha256:hash(x.actor||''),requestSha256:hash(x.request_payload),name:x.request_payload?.rascunho?.nome,brand:x.request_payload?.rascunho?.marca,channel:x.request_payload?.rascunho?.canal,status:x.resposta?.status,draft_id:x.resposta?.body?.draft_id,version:x.resposta?.body?.version,state:x.resposta?.body?.estado,contentSha256:hash(x.request_payload?.rascunho||{})}));
 }
 if(out.columns.some(x=>x.table_name==='shrigma_template_draft')){
   const result=await pg.query("SELECT draft_id,brand,channel,nome,version,estado,rascunho,components FROM public.shrigma_template_draft WHERE nome=$1 LIMIT 20",['teste-emails-fish']);
   out.modelDrafts=result.rows.map(x=>({id:x.draft_id,brand:x.brand,channel:x.channel,name:x.nome,version:x.version,state:x.estado,contentSha256:hash(x.rascunho),componentsSha256:hash(x.components)}));
 }
 await pg.query('COMMIT');await pg.end();clearTimeout(timer);console.log('CRM_DATABASE_READ_PROOF '+JSON.stringify(out));
}
main().catch(async e=>{clearTimeout(timer);try{await pg.query('ROLLBACK');await pg.end();}catch{}console.error('CRM_READ_TASK_FAILED '+JSON.stringify({code:/^[A-Za-z0-9_]{1,40}$/.test(e.code||'')?e.code:null}));process.exitCode=1;});
